with unpacked as (select id, service, host, log_ts, latency_ms, context['region'] as region, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries as retry_count, array_contains(map_keys(context), 'region') as has_region, shiftright(status_code, 2) as status_code_high from app_logs) select id, service, host, region, has_region, row_number() over (partition by service order by retry_count asc, id asc) as event_seq, row_number() over (order by latency_ms asc, id asc) as seq_no, last_value(retry_count, true) over (partition by service order by retry_count asc, id asc rows between unbounded preceding and current row) as last_known_retry_count, row_number() over (partition by host order by log_ts asc, id asc) as row_seq from unpacked
